  function get_string_from_ptr(ptr)
  {
	var ret = "";

	if (ptr == 0)
		return ret;

	var i = 0;
	while (1) {
  //    if ((ptr.pos + i) >= ptr.slab.length) { return "<< Invalid read: " + (ptr.pos+i) + " : " + ptr.slab.length + " >>"; } else {}
	if (heapU8[ptr + i] == 0)
		break;

      var t = String.fromCharCode(heapU8[ptr + i]);
      ret += t;
      i += 1;
    }

	return ret;
  }

  function fill_ptr_from_string(ptr, v)
  {
	var j;
	var len = v.length;
	var data;

  	for(j = 0; j < len; j++)
	{
		data = v.charCodeAt(j);

		heapU8[ptr] = data;
		ptr++;
	}
		heapU8[ptr] = 0;
	}

