var CodeLoad = new BenchmarkSuite('CodeLoad', [450000], [
  new Benchmark('CodeLoadClosure',
                false,
                false,
                1600,
                runCodeLoadClosure,
                setupCodeLoad,
                tearDownCodeLoad,
                null,
                16),
  new Benchmark('CodeLoadJQuery',
                false,
                false,
                100,
                runCodeLoadJQuery,
                setupCodeLoad,
                tearDownCodeLoad,
                null,
                16)
]);

var salt;
var indirectEval;

function setupCodeLoad() {
  salt = 0;
  indirectEval = eval;
}

function tearDownCodeLoad() {
  salt = null;
  indirectEval = null;
}

function runCodeLoadClosure() {
  runClosure();
  salt++;
}

function runCodeLoadJQuery() {
  runJQuery();
  salt++;
}

